 const cpfValid=raw=>{const c=raw.replace(/\D/g,'');if(!/^\d{11}$/.test(c)||/^(\d)\1{10}$/.test(c))return false;for(let n=9;n<=10;n++){let sum=0;for(let i=0;i<n;i++)sum+=Number(c[i])*(n+1-i);let d=(sum*10)%11;if((d===10?0:d)!==Number(c[n]))return false;}return true;};
